'use strict';

// MAIN //

var unvalidated = [];

unvalidated.push({
	'code': [
		'var x = foo();',
		'x.bar();',
		'x.bar();'
	].join( '\n' )
});

unvalidated.push({
	'code': [
		'var x = require( name );',
		'x.bar();'
	].join( '\n' )
});

unvalidated.push({
	'code': [
		'var { a } = require( \'foo\' );',
		'a();'
	].join( '\n' ),
	'parserOptions': {
		'ecmaVersion': 6
	}
});

unvalidated.push({
	'code': [
		'var x = require( \'foo\', \'bar\' );',
		'x.baz();'
	].join( '\n' )
});


// EXPORTS //

module.exports = unvalidated;
